// SPDX-License-Identifier: Apache-2.0
/**
 * build.mjs — the SCF documentation site.
 *
 *   npm run build      write site/dist
 *   npm run check      build to a temp dir and verify; write nothing
 *
 * WHAT THIS DOES NOT DO.
 *
 * It authors nothing. Every page is a Markdown file that already exists
 * in the repository and is already reviewed, checksummed or generated by
 * something else. A documentation site that carried its own copy of the
 * specification would be the same defect this project keeps finding —
 * one thing described in two places, drifting — except with the drifting
 * copy on the internet.
 *
 * The one exception is `index.md`, which is the landing page and is
 * meant to be written by a person. It is the only file here with
 * content of its own.
 *
 * WHAT IT ADDS, AND WHY IT IS WORTH A BUILD STEP.
 *
 * §-REFERENCES BECOME LINKS. The specification cross-references itself
 * constantly — "(§12.1.2)", "spec §6.6.1", "§4.5 pattern 2" — and in
 * plain Markdown every one of those is dead text. Three independent
 * implementations have been written by people reading this document,
 * and all three of them navigated it by scrolling.
 *
 * AND A DANGLING REFERENCE FAILS THE BUILD. Resolving them means
 * knowing which sections exist, which means knowing when one does not.
 * A `§9.7` in prose when §9 stops at §9.6 is a defect a reader finds by
 * losing ten minutes; here it stops CI. That check is the reason this
 * is a generator rather than a Jekyll config.
 */

import { marked } from "marked";
import {
  cpSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const CHECK = process.argv.includes("--check");
const OUT = CHECK ? mkdtempSync(join(tmpdir(), "scf-site-")) : join(HERE, "dist");

/**
 * The site, in nav order. `source` is repository-relative; nothing here
 * is written by this package except index.md.
 *
 * `anchors: true` marks a document whose own §N.N headings define
 * section numbers other documents may reference. Only the spec does.
 */
const PAGES = [
  { group: "", title: "SCF", slug: "index", source: "site/index.md",
    blurb: "What the format is" },

  { group: "Specification", title: "The specification",
    slug: "spec", source: "spec/scf-spec.md", anchors: true,
    blurb: "Normative. Everything the format requires" },
  { group: "Specification", title: "Conformance",
    slug: "conformance", source: "spec/conformance.md",
    blurb: "The three roles, and how a claim is made" },
  { group: "Specification", title: "Stability",
    slug: "stability", source: "spec/stability.md",
    blurb: "What is safe to build against" },
  { group: "Specification", title: "Changelog",
    slug: "changelog", source: "spec/CHANGELOG.md", historical: true,
    blurb: "Every revision, and why" },

  { group: "Reference", title: "Entities",
    slug: "entities", source: "spec/entity-reference.md",
    blurb: "All 99 entities and their fields. Generated" },
  { group: "Reference", title: "Queries",
    slug: "queries", source: "spec/query-reference.md",
    blurb: "The sixteen canonical queries. Generated" },
  { group: "Reference", title: "Published artifacts",
    slug: "artifacts", source: "spec/ARTIFACTS.md",
    blurb: "Addressable and checksummed. Generated" },

  { group: "Contributing", title: "How to contribute",
    slug: "contributing", source: "CONTRIBUTING.md",
    blurb: "Which of the three routes a change takes" },
  { group: "Contributing", title: "Proposals",
    slug: "proposals", source: "proposals/README.md",
    blurb: "Where a change to the format gets argued" },
  { group: "Contributing", title: "Governance",
    slug: "governance", source: "GOVERNANCE.md",
    blurb: "Who decides, and what they weigh" },
  { group: "Contributing", title: "Security",
    slug: "security", source: "SECURITY.md",
    blurb: "What is in scope, and how to report" },

  { group: "Design record", title: "Why it is like this",
    slug: "conventions", source: "docs/conventions.md",
    blurb: "The design record. States no rules" },
  { group: "Design record", title: "Story structure",
    slug: "story-structure", source: "docs/story-structure-design-record.md",
    blurb: "Spans, boundaries and the shoot surface" },
  { group: "Design record", title: "Release checklist",
    slug: "release-checklist", source: "docs/release-checklist.md",
    blurb: "What stands between here and 1.0" },
];

const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;")
  .replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// ── Pass one: read every page, and learn which sections exist ────────
const docs = [];
const sections = new Map();   // "12.1.2" -> { slug, id, title }

for (const page of PAGES) {
  let text;
  try {
    text = readFileSync(join(ROOT, page.source), "utf8");
  } catch {
    console.error(`[site] missing source: ${page.source}`);
    process.exit(1);
  }
  // The SPDX comment is repository bookkeeping, not page content.
  text = text.replace(/^<!--\s*SPDX-License-Identifier:[^>]*-->\s*\n/, "");

  const headings = [];
  for (const line of text.split("\n")) {
    const m = /^(#{1,6})\s+(.+?)\s*$/.exec(line);
    if (!m) continue;
    const title = m[2].replace(/[`*]/g, "");
    const num = /^(\d+(?:\.\d+)*)\.?\s+/.exec(title);
    const id = num
      ? `s${num[1].replace(/\./g, "-")}`
      : title.toLowerCase().replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");
    headings.push({ level: m[1].length, title, id, number: num?.[1] ?? null });
    if (page.anchors && num) {
      sections.set(num[1], { slug: page.slug, id, title });
    }
  }
  docs.push({ page, text, headings });
}

// ── §-reference resolution ───────────────────────────────────────────
const dangling = [];

/**
 * Rewrite §N.N into a link, and record any that names no section.
 *
 * Deliberately narrow: only a `§` immediately followed by digits. Prose
 * says "section 9" and "§9.4 and §9.5" and "conformance.md §2.2", and
 * guessing at the looser forms would produce wrong links, which are
 * worse than none.
 *
 * A reference in a document OTHER than the spec still resolves against
 * the spec's sections, because that is what those documents mean by §.
 */
function linkSections(html, selfSlug, historical = false) {
  return html.replace(/§(\d+(?:\.\d+)*)/g, (whole, num) => {
    const hit = sections.get(num);
    if (hit === undefined) {
      // Trailing-punctuation case: "§9." is a reference to §9.
      const trimmed = num.replace(/\.$/, "");
      const alt = sections.get(trimmed);
      if (alt !== undefined) {
        const href = alt.slug === selfSlug ? `#${alt.id}`
          : `${alt.slug}.html#${alt.id}`;
        return `<a class="xref" href="${href}" title="${esc(alt.title)}">` +
               `§${trimmed}</a>.`;
      }
      // A CHANGELOG legitimately names sections that no longer exist:
      // §4.3.1 was added in 0.16 and deleted in 0.21, and both entries
      // are correct about the document as it stood. Recording history
      // is the one place a reference to something gone is not a defect.
      // Everywhere else it sends a reader looking for nothing.
      if (historical) return whole;
      dangling.push({ ref: `§${num}`, slug: selfSlug });
      return `<span class="xref-dead" title="no such section">${whole}</span>`;
    }
    const href = hit.slug === selfSlug ? `#${hit.id}`
      : `${hit.slug}.html#${hit.id}`;
    return `<a class="xref" href="${href}" title="${esc(hit.title)}">` +
           `${whole}</a>`;
  });
}

// ── Render ───────────────────────────────────────────────────────────
marked.use({
  renderer: {
    heading({ tokens, depth }) {
      const title = this.parser.parseInline(tokens);
      const plain = title.replace(/<[^>]+>/g, "");
      const num = /^(\d+(?:\.\d+)*)\.?\s+/.exec(plain);
      const id = num
        ? `s${num[1].replace(/\./g, "-")}`
        : plain.toLowerCase().replace(/[^a-z0-9]+/g, "-")
          .replace(/^-|-$/g, "");
      return `<h${depth} id="${id}">${title}` +
             `<a class="anchor" href="#${id}" aria-label="link">#</a>` +
             `</h${depth}>\n`;
    },
  },
});

function nav(currentSlug) {
  const groups = [];
  for (const page of PAGES) {
    let g = groups.find((x) => x.name === page.group);
    if (g === undefined) { g = { name: page.group, pages: [] }; groups.push(g); }
    g.pages.push(page);
  }
  return groups.map((g) => {
    const items = g.pages.map((p) =>
      `<li${p.slug === currentSlug ? ' class="here"' : ""}>` +
      `<a href="${p.slug}.html">${esc(p.title)}</a></li>`).join("");
    return (g.name ? `<h2>${esc(g.name)}</h2>` : "") + `<ul>${items}</ul>`;
  }).join("");
}

/** On-page contents. Deep documents are unusable without one. */
function contents(headings) {
  const useful = headings.filter((h) => h.level >= 2 && h.level <= 3);
  if (useful.length < 4) return "";
  const items = useful.map((h) =>
    `<li class="l${h.level}"><a href="#${h.id}">${esc(h.title)}</a></li>`)
    .join("");
  return `<nav class="toc"><h2>On this page</h2><ul>${items}</ul></nav>`;
}

const built = [];
for (const { page, text, headings } of docs) {
  const body = linkSections(marked.parse(text), page.slug,
                            page.historical === true);
  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(page.title)} — SCF</title>
<meta name="description" content="${esc(page.blurb)}">
<link rel="stylesheet" href="style.css">
</head>
<body>
<a class="skip" href="#content">Skip to content</a>
<div class="shell">
<aside class="side">
<a class="brand" href="index.html">SCF</a>
<p class="tagline">Story Context Framework</p>
${nav(page.slug)}
<p class="repo"><a href="https://github.com/MinimalHumans/SCF_studio">Repository</a></p>
</aside>
<main id="content">
${contents(headings)}
<article>
${body}
</article>
<footer>
<p>Rendered from <code>${esc(page.source)}</code>. The repository is the
source of truth; if this page disagrees with it, the repository is right.</p>
</footer>
</main>
</div>
</body>
</html>
`;
  built.push({ slug: page.slug, html });
}

// ── A dangling cross-reference is a defect, not a cosmetic problem ───
if (dangling.length > 0) {
  const seen = new Set();
  console.error("[site] cross-references that name no section:\n");
  for (const d of dangling) {
    const key = `${d.slug}:${d.ref}`;
    if (seen.has(key)) continue;
    seen.add(key);
    console.error(`  ${d.ref}  in ${d.slug}`);
  }
  console.error("\n  Either the section was renumbered and something still " +
                "points at the old\n  number, or the reference is a typo. " +
                "Both send a reader looking for\n  something that is not " +
                "there.");
  if (CHECK) rmSync(OUT, { recursive: true, force: true });
  process.exit(1);
}

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
for (const { slug, html } of built) {
  writeFileSync(join(OUT, `${slug}.html`), html, "utf8");
}
cpSync(join(HERE, "style.css"), join(OUT, "style.css"));
writeFileSync(join(OUT, ".nojekyll"), "", "utf8");

const summary = `${String(built.length)} pages, ` +
  `${String(sections.size)} linkable sections`;
if (CHECK) {
  rmSync(OUT, { recursive: true, force: true });
  console.log(`[site] builds clean (${summary}).`);
} else {
  console.log(`[site] wrote site/dist — ${summary}.`);
}
